// Which sensor readings may be used. A reading counts only when the value exists and its status does not say it is
// missing or wrong. Old words ("normal") written by early versions of the ingest function are still accepted.

export interface ReadingInput {
  sensorPointId: string;
  measuredAt: string;
  moisture: number | null;
  moistureStatus: string | null;
}

const NOT_USABLE = new Set(['not_measured', 'suspect', 'sensor_error']);

export function usableMoisture(r: ReadingInput): number | null {
  const v = r.moisture;
  if (v === null || v === undefined || !Number.isFinite(v)) return null;
  if (v < 0 || v > 100) return null;
  if (r.moistureStatus && NOT_USABLE.has(r.moistureStatus)) return null;
  return v;
}

/** newest usable moisture of one sensor point that is not older than maxAgeHours (and not from the future) */
export function latestFreshMoisture(
  readings: ReadingInput[],
  pointId: string,
  nowMs: number,
  maxAgeHours: number,
): { value: number; measuredAt: string } | null {
  let best: { value: number; measuredAt: string; ms: number } | null = null;
  for (const r of readings) {
    if (r.sensorPointId !== pointId) continue;
    const ms = Date.parse(r.measuredAt);
    if (!Number.isFinite(ms) || ms > nowMs || nowMs - ms > maxAgeHours * 3_600_000) continue;
    const v = usableMoisture(r);
    if (v === null) continue;
    if (!best || ms > best.ms) best = { value: v, measuredAt: r.measuredAt, ms };
  }
  return best ? { value: best.value, measuredAt: best.measuredAt } : null;
}
